package org.apache.commons.codec.binary;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class BinaryCodecTest_testEncodeByteArray {

    private static final int BIT_0 = 0x01;
    private static final int BIT_1 = 0x02;
    private static final int BIT_2 = 0x04;
    private static final int BIT_3 = 0x08;
    private static final int BIT_4 = 0x10;
    private static final int BIT_5 = 0x20;
    private static final int BIT_6 = 0x40;
    private static final int BIT_7 = 0x80;

    private static final byte ALL_BITS = (byte) (BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6 | BIT_7);

    private BinaryCodec instance;

    @BeforeEach
    void setUp() {
        this.instance = new BinaryCodec();
    }

    @AfterEach
    void tearDown() {
        this.instance = null;
    }

    @Test
    void testEncodeByteArray() {
        assertEncodesTo("00000000", new byte[1]);
        assertEncodesTo("00000001", oneByte(BIT_0));
        assertEncodesTo("00000011", oneByte(BIT_0 | BIT_1));
        assertEncodesTo("00000111", oneByte(BIT_0 | BIT_1 | BIT_2));
        assertEncodesTo("00001111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3));
        assertEncodesTo("00011111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4));
        assertEncodesTo("00111111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5));
        assertEncodesTo("01111111", oneByte(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6));
        assertEncodesTo("11111111", oneByte(ALL_BITS));

        assertEncodesTo("0000000000000000", new byte[2]);
        assertEncodesTo("0000000000000001", twoBytes(BIT_0, 0));
        assertEncodesTo("0000000000000011", twoBytes(BIT_0 | BIT_1, 0));
        assertEncodesTo("0000000000000111", twoBytes(BIT_0 | BIT_1 | BIT_2, 0));
        assertEncodesTo("0000000000001111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3, 0));
        assertEncodesTo("0000000000011111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4, 0));
        assertEncodesTo("0000000000111111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5, 0));
        assertEncodesTo("0000000001111111", twoBytes(BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6, 0));
        assertEncodesTo("0000000011111111", twoBytes(ALL_BITS, 0));

        assertEncodesTo("0000000111111111", twoBytes(ALL_BITS, BIT_0));
        assertEncodesTo("0000001111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1));
        assertEncodesTo("0000011111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2));
        assertEncodesTo("0000111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3));
        assertEncodesTo("0001111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4));
        assertEncodesTo("0011111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5));
        assertEncodesTo("0111111111111111", twoBytes(ALL_BITS, BIT_0 | BIT_1 | BIT_2 | BIT_3 | BIT_4 | BIT_5 | BIT_6));
        assertEncodesTo("1111111111111111", twoBytes(ALL_BITS, ALL_BITS));

        assertEquals(0, instance.encode((byte[]) null).length);
    }

    private void assertEncodesTo(final String expected, final byte[] bits) {
        final String encoded = new String(instance.encode(bits));
        assertEquals(expected, encoded);
    }

    private static byte[] oneByte(final int value) {
        final byte[] bits = new byte[1];
        bits[0] = (byte) value;
        return bits;
    }

    private static byte[] twoBytes(final int lowByte, final int highByte) {
        final byte[] bits = new byte[2];
        bits[0] = (byte) lowByte;
        bits[1] = (byte) highByte;
        return bits;
    }
}
